-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- feedback-day-after
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal: thank you and feedback',
  'Thank you for being part of Signal',
  'Tell us how the day was. Every piece of feedback shapes what we do next.',
  'ticket-purchasers',
  $nl$[{"id":"feedback-day-after-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/community.jpg","alt":"Attendees at a TEDxNewy event applauding","widthPct":"full"},{"id":"feedback-day-after-02","type":"header","text":"Thank you for being part of Signal.","size":"lg"},{"id":"feedback-day-after-03","type":"text","html":"<p>Yesterday, a room full of Novocastrians came together to share ideas, and you were one of them. Thank you for being there.</p><p>We hope it was a day filled with ideas that challenged you, inspired you and sparked new thinking.</p><p>A signal only matters when someone receives it. Every idea shared yesterday now travels on with you, and the ripple starts with what you do next.</p>"},{"id":"feedback-day-after-04","type":"image","src":"https://tedxnewy.com.au/images/newsletter/artwork-authenticity.jpg","alt":"Authenticity, an artwork by Jenni Jean: rows of red fingerprints with a single gold one","widthPct":80},{"id":"feedback-day-after-05","type":"divider","style":"short","colour":"soft"},{"id":"feedback-day-after-06","type":"header","text":"Tell us how we did","size":"md"},{"id":"feedback-day-after-07","type":"text","html":"<p>Feedback is how we keep improving the events we deliver. Our team reads every response and takes each piece of it seriously.</p><p>It takes a couple of minutes, and it makes a real difference to what we do next.</p>"},{"id":"feedback-day-after-08","type":"button","label":"Share your feedback","href":"https://tedxnewy.com.au/feedback","align":"center","theme":"red","variant":"solid"},{"id":"feedback-day-after-09","type":"divider","style":"short","colour":"soft"},{"id":"feedback-day-after-10","type":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-hero.jpg","alt":"A packed audience at a TEDxNewy event","widthPct":100},{"id":"feedback-day-after-11","type":"header","text":"Come aboard the team","size":"md"},{"id":"feedback-day-after-12","type":"text","html":"<p>TEDxNewy is run entirely by volunteers. If yesterday made you want to be part of making it happen, we'd love to hear from you.</p>"},{"id":"feedback-day-after-13","type":"button","label":"Apply to volunteer","href":"https://tedxnewy.com.au/volunteer","align":"center","theme":"ink","variant":"outline"},{"id":"feedback-day-after-14","type":"text","html":"<p>Thank you again.</p><p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal: thank you and feedback'
);
